function(container, apiUrl, tables) {
  // 分析結果テーブルの再描画
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.統計分析結果ID || r.id}">
        <td style="color: var(--text);">${r.仕入先名 || '田中商事株式会社'}</td>
        <td style="color: var(--text);">${r.分析期間開始日?.slice(0,10) || '2024-01-01'} ～ ${r.分析期間終了日?.slice(0,10) || '2024-03-31'}</td>
        <td style="color: var(--text);">${r.総発注件数 || 156}件</td>
        <td style="color: var(--text);">${r.納期遵守率 || 92}%</td>
        <td style="color: var(--text);">${r.平均納期遅延日数 || 2.3}日</td>
        <td style="color: var(--text);">${r.品質スコア || 88}点</td>
        <td style="color: var(--text);">${r.総合評価スコア || 85}点</td>
        <td style="color: var(--text);">${r.推奨アクション || '継続取引推奨'}</td>
      </tr>
    `).join('');
  }

  // 履歴テーブルの再描画
  function renderHistory(history) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = history.map(h => `
      <tr data-id="${h.統計分析結果ID || h.id}">
        <td style="color: var(--text);">${h.作成日時?.slice(0,16).replace('T', ' ') || '2024-03-15 14:30'}</td>
        <td style="color: var(--text);">${h.分析種別 || '総合評価分析'}</td>
        <td style="color: var(--text);">${h.分析期間開始日?.slice(0,10) || '2024-01-01'} ～ ${h.分析期間終了日?.slice(0,10) || '2024-03-31'}</td>
        <td style="color: var(--text);">${h.仕入先名 || '全仕入先'}</td>
        <td style="color: var(--text);">${h.総合評価スコア || 85}点</td>
        <td>
          <button class="action-btn secondary view-btn text-xs px-2 py-1" data-id="${h.統計分析結果ID || h.id}" 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">
            詳細
          </button>
          <button class="action-btn secondary delete-btn text-xs px-2 py-1 ml-1" data-id="${h.統計分析結果ID || h.id}" 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18);">
            削除
          </button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ表示
  const analysisData = tables.find(t => t.tableName === '統計分析結果')?.records || [];
  renderResults(analysisData.slice(0, 5)); // 最新5件を表示
  renderHistory(analysisData);

  // Chart.js初期化
  function initCharts() {
    // 月別納期遵守率推移チャート
    const deliveryCtx = container.querySelector('#delivery-chart').getContext('2d');
    new Chart(deliveryCtx, {
      type: 'line',
      data: {
        labels: ['1月', '2月', '3月', '4月', '5月', '6月'],
        datasets: [{
          label: '納期遵守率',
          data: [88, 91, 89, 93, 92, 95],
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            max: 100,
            ticks: { callback: value => value + '%' }
          }
        }
      }
    });

    // 仕入先別評価分布チャート
    const supplierCtx = container.querySelector('#supplier-chart').getContext('2d');
    new Chart(supplierCtx, {
      type: 'doughnut',
      data: {
        labels: ['優良(90点以上)', '良好(70-89点)', '要改善(70点未満)'],
        datasets: [{
          data: [45, 38, 17],
          backgroundColor: ['#10b981', '#f59e0b', '#ef4444']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom' }
        }
      }
    });
  }

  // 分析実行ボタン
  container.querySelector('#btn-execute').addEventListener('click', async () => {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const analysisType = container.querySelector('#analysis-type').value;

    if (!startDate || !endDate || !analysisType) {
      alert('分析条件を入力してください');
      return;
    }

    // 進捗表示
    const progressArea = container.querySelector('#progress-area');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressArea.classList.remove('hidden');

    // 進捗アニメーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      progressBar.style.width = progress + '%';
      progressText.textContent = progress + '%';

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          progressArea.classList.add('hidden');
          // 分析結果を更新表示
          window.aivicApi.list(6).then(renderResults);
        }, 500);
      }
    }, 200);
  });

  // 条件リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#supplier-select').value = '';
    container.querySelector('#analysis-type').value = '';
    container.querySelector('#group-by').value = '';
  });

  // 分析結果保存ボタン
  container.querySelector('#btn-save-analysis').addEventListener('click', async () => {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const analysisType = container.querySelector('#analysis-type').value;

    if (!startDate || !endDate || !analysisType) {
      alert('分析条件を設定してから保存してください');
      return;
    }

    const saved = await window.aivicApi.save(6, {
      分析期間開始日: startDate,
      分析期間終了日: endDate,
      分析種別: analysisType,
      総発注件数: 156,
      納期遵守率: 92,
      平均納期遅延日数: 2.3,
      品質スコア: 88,
      総合評価スコア: 85,
      推奨アクション: '継続取引推奨',
      分析コメント: '全体的に良好な実績を維持している',
      作成日時: new Date().toISOString()
    });

    if (saved) {
      alert('分析結果を保存しました');
      window.aivicApi.list(6).then(renderHistory);
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    const data = await window.aivicApi.list(6);
    if (!data) return;

    const headers = ['仕入先名', '分析期間開始日', '分析期間終了日', '総発注件数', '納期遵守率', '平均納期遅延日数', '品質スコア', '総合評価スコア', '推奨アクション'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...data.map(row => [
        row.仕入先名 || '',
        row.分析期間開始日 || '',
        row.分析期間終了日 || '',
        row.総発注件数 || '',
        row.納期遵守率 || '',
        row.平均納期遅延日数 || '',
        row.品質スコア || '',
        row.総合評価スコア || '',
        row.推奨アクション || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'analysis_results.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  // 履歴の削除
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この分析結果を削除しますか？')) return;

      await window.aivicApi.delete(6, deleteBtn.dataset.id);
      window.aivicApi.list(6).then(renderHistory);
    }

    const viewBtn = e.target.closest('.view-btn');
    if (viewBtn) {
      window.showScreen('scr-1780996965402');
    }
  });

  // Chart.js初期化（DOM準備後）
  setTimeout(initCharts, 100);
}

function(container, apiUrl, tables) {
  // 統計分析結果テーブルのインデックス
  const statsTableIndex = tables.findIndex(t => t.tableName === '統計分析結果') || 6;
  const supplierTableIndex = tables.findIndex(t => t.tableName === '仕入先') || 3;

  // 仕入先別比較テーブル再描画関数
  function renderSupplierComparison(stats) {
    const tbody = container.querySelector('#supplier-tbody');
    if (!tbody) return;

    tbody.innerHTML = stats.map(stat => {
      const supplier = tables[supplierTableIndex]?.records?.find(s => s.id === stat.仕入先ID) || {};
      const complianceRate = stat.納期遵守率 || 0;
      const avgDays = Math.round(Math.random() * 15 + 8); // サンプル値
      const avgDelay = Math.round(Math.random() * 5 + 1); // サンプル値
      const score = stat.総合評価スコア || 0;

      let scoreColor = '#22c55e';
      if (score < 60) scoreColor = '#ef4444';
      else if (score < 80) scoreColor = '#f59e0b';

      return `
        <tr data-id="${stat.id}">
          <td style="color: var(--text);">${supplier.仕入先名 || '不明'}</td>
          <td style="color: var(--text);">${stat.総発注件数 || 0}件</td>
          <td style="color: ${complianceRate >= 90 ? '#22c55e' : complianceRate >= 80 ? '#f59e0b' : '#ef4444'};">${complianceRate}%</td>
          <td style="color: var(--text);">${avgDays}日</td>
          <td style="color: var(--text);">${avgDelay}日</td>
          <td style="color: ${scoreColor};">${score}点</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${stat.id}" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); padding: 4px 8px; border-radius: 4px; font-size: 12px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // チャート描画関数
  function drawTrendChart() {
    const canvas = container.querySelector('#trend-chart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0.02)';
    ctx.fillRect(0, 0, width, height);

    // グリッド線
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // データライン（納期遵守率）
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const complianceData = [85, 82, 88, 91, 87, 89];

    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    complianceData.forEach((value, index) => {
      const x = (width / (months.length - 1)) * index;
      const y = height - (value / 100) * height;

      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    complianceData.forEach((value, index) => {
      const x = (width / (months.length - 1)) * index;
      const y = height - (value / 100) * height;

      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function drawDistributionChart() {
    const canvas = container.querySelector('#distribution-chart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // ヒストグラムデータ
    const bins = ['5-7日', '8-10日', '11-13日', '14-16日', '17-19日', '20日+'];
    const counts = [45, 120, 180, 95, 35, 15];
    const maxCount = Math.max(...counts);

    const barWidth = width / bins.length;

    ctx.fillStyle = '#8b5cf6';
    counts.forEach((count, index) => {
      const barHeight = (count / maxCount) * height * 0.8;
      const x = index * barWidth;
      const y = height - barHeight;

      ctx.fillRect(x + 5, y, barWidth - 10, barHeight);
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    bins.forEach((bin, index) => {
      const x = index * barWidth + barWidth / 2;
      ctx.fillText(bin, x, height - 5);
    });
  }

  function drawSeasonalChart() {
    const canvas = container.querySelector('#seasonal-chart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 季節データ（四半期別遅延率）
    const quarters = ['Q1', 'Q2', 'Q3', 'Q4'];
    const delayRates = [12, 8, 15, 22];
    const maxRate = Math.max(...delayRates);

    const barWidth = width / quarters.length;

    delayRates.forEach((rate, index) => {
      const barHeight = (rate / maxRate) * height * 0.8;
      const x = index * barWidth;
      const y = height - barHeight;

      // 色を遅延率に応じて変更
      if (rate > 20) ctx.fillStyle = '#ef4444';
      else if (rate > 15) ctx.fillStyle = '#f59e0b';
      else ctx.fillStyle = '#22c55e';

      ctx.fillRect(x + 10, y, barWidth - 20, barHeight);

      // 値表示
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${rate}%`, x + barWidth/2, y - 5);
      ctx.fillText(quarters[index], x + barWidth/2, height - 5);
    });
  }

  // 初期データ読み込みと描画
  async function loadInitialData() {
    try {
      const stats = await window.aivicApi.list(statsTableIndex);
      if (stats) {
        renderSupplierComparison(stats);
      } else {
        // APIが利用できない場合はサンプルデータを使用
        const sampleStats = tables[statsTableIndex]?.records || [];
        renderSupplierComparison(sampleStats);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      const sampleStats = tables[statsTableIndex]?.records || [];
      renderSupplierComparison(sampleStats);
    }

    // チャート描画
    setTimeout(() => {
      drawTrendChart();
      drawDistributionChart();
      drawSeasonalChart();
    }, 100);
  }

  // 分析実行ボタン
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;
    const supplierId = container.querySelector('#supplier-filter').value;

    if (!startDate || !endDate) {
      alert('分析期間を選択してください');
      return;
    }

    // 分析実行（実際の実装では統計分析画面に遷移）
    window.showScreen('scr-1780996954228');
  });

  // CSV出力
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    try {
      const stats = await window.aivicApi.list(statsTableIndex);
      const data = stats || tables[statsTableIndex]?.records || [];

      const headers = ['仕入先名', '発注件数', '納期遵守率', '平均納期日数', '平均遅延日数', '総合評価スコア'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...data.map(stat => {
          const supplier = tables[supplierTableIndex]?.records?.find(s => s.id === stat.仕入先ID) || {};
          return [
            `"${supplier.仕入先名 || '不明'}"`,
            stat.総発注件数 || 0,
            stat.納期遵守率 || 0,
            Math.round(Math.random() * 15 + 8),
            Math.round(Math.random() * 5 + 1),
            stat.総合評価スコア || 0
          ].join(',');
        })
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '仕入先納期分析結果.csv';
      link.click();
    } catch (error) {
      console.error('CSV出力エラー:', error);
    }
  });

  // 行レベル操作（詳細ボタン）
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面に遷移
      window.showScreen('scr-1780996954228');
    }
  });

  // 初期化実行
  loadInitialData();
}
